const jobs = [];
const rawItems = $input.all();

for (const item of rawItems) {
  const data = item.json;
  // RemoteOK returns an array; first element is metadata (has 'legal' field)
  const jobList = Array.isArray(data) ? data.filter(j => j.id && !j.legal) : [data];
  for (const job of jobList) {
    if (!job.id) continue;
    jobs.push({
      job_title: job.position || job.title || '',
      company: job.company || '',
      job_url: job.url || `https://remoteok.com/jobs/${job.id}`,
      source: 'Remote OK',
      location_text: job.location || 'worldwide',
      salary: job.salary_min ? `$${job.salary_min}–$${job.salary_max || job.salary_min}` : '',
      description: (job.description || '').replace(/<[^>]+>/g, ' '),
      posted_date: job.date || '',
      tags: Array.isArray(job.tags) ? job.tags.join(', ') : (job.tags || ''),
      job_id: String(job.id)
    });
  }
}
return jobs.map(j => ({ json: j }));

