const allItems = $input.all();
const existingItems = allItems.filter(i => i.json._source_type === 'existing');
const newItems = allItems.filter(i => i.json._source_type === 'new');

const existingUrls = new Set(
  existingItems.map(i => (i.json.job_url || '').trim().toLowerCase()).filter(Boolean)
);
const existingKeys = new Set(
  existingItems.map(i => {
    const c = (i.json.company || '').toLowerCase().trim();
    const t = (i.json.job_title || '').toLowerCase().trim();
    return `${c}::${t}`;
  }).filter(k => k !== '::')
);

return newItems.filter(item => {
  const url = (item.json.job_url || '').trim().toLowerCase();
  if (url && existingUrls.has(url)) return false;
  const key = `${(item.json.company || '').toLowerCase().trim()}::${(item.json.job_title || '').toLowerCase().trim()}`;
  if (key !== '::' && existingKeys.has(key)) return false;
  return true;
}).map(item => {
  const j = { ...item.json };
  delete j._source_type;
  return { json: j };
});

const REJECT_PATTERNS = [
  /\bus[- ]only\b/i, /\busa[- ]only\b/i, /\bunited states only\b/i,
  /\bcanada[- ]only\b/i, /\buk[- ]only\b/i, /\bunited kingdom only\b/i,
  /\beu[- ]only\b/i, /\beurope[- ]only\b/i, /\baustralia[- ]only\b/i,
  /\bmust be (physically )?based in\b/i, /\bmust live in\b/i,
  /\bmust be authorized to work in\b/i, /\bwork authorization required\b/i,
  /\blocal work permit required\b/i, /\brequires? (a )?(valid )?work (permit|visa|authorization)\b/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i, /\bin-office\b/i,
  /\boffice required\b/i, /\boffice-based\b/i,
  /\bremote within (the )?(us|usa|uk|eu|europe|canada|australia|one country)\b/i,
  /\bfixed us (business )?hours\b/i, /\bfixed eu (business )?hours\b/i,
  /\best hours required\b/i, /\bpst hours required\b/i,
  /\bauthorized to work in the (us|usa|uk|eu|europe|canada|australia)\b/i,
  /\bmust reside in\b/i, /\bresident of (the )?(us|usa|uk|eu|europe|canada|australia)\b/i,
  /\brelocation required\b/i, /\bmust relocate\b/i,
  /\b(us|uk|eu|canada|australia|europe) (work )?authorization\b/i
];

const passed = [];
const rejected = [];

for (const item of $input.all()) {
  const text = [
    item.json.location_text || '',
    item.json.description || '',
    item.json.tags || ''
  ].join(' ');

  let rejectReason = null;
  for (const pat of REJECT_PATTERNS) {
    if (pat.test(text)) {
      rejectReason = pat.source;
      break;
    }
  }

  if (rejectReason) {
    rejected.push({ json: { ...item.json, _hard_reject_reason: rejectReason } });
  } else {
    passed.push({ json: item.json });
  }
}

// Store rejected for later; return only passed
// Note: connect this node's output to both Save Raw and AI Check
// Rejected items are emitted on output 1 via the IF node downstream
return passed;

const KEYWORDS = [
  'async', 'asynchronous', 'worldwide remote', 'global remote',
  'work from anywhere', 'remote data analyst', 'remote data scientist',
  'remote ai marketing', 'remote marketing analyst', 'remote growth analyst',
  'remote bi analyst', 'remote automation', 'remote ai workflow',
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'performance marketing', 'growth analyst',
  'ai marketing', 'ai automation', 'ai workflow', 'creative strategist',
  'martech analyst', 'marketing data'
];

return $input.all().filter(item => {
  const text = [
    item.json.job_title || '',
    item.json.description || '',
    item.json.tags || ''
  ].join(' ').toLowerCase();
  return KEYWORDS.some(kw => text.includes(kw.toLowerCase()));
}).map(item => ({ json: item.json }));

const job = $input.item.json;
const desc = (job.description || '').substring(0, 2500);

const prompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule:
Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."

Reject the job if it requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan.
Reject the job if it requires local work authorization outside Taiwan.
Reject the job if it is hybrid, onsite, or remote within one country only.
Reject the job if it requires fixed working hours that would force Jerry to work through the night in Taiwan.

Keep the job only if one of these is true:
- The job says worldwide remote.
- The job says work from anywhere.
- The job says global remote.
- The job says APAC remote.
- The job allows international contractors.
- The job accepts people based anywhere.
- The company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement.

Return JSON only:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "short reason",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}

Job post:
Title: ${job.job_title}
Company: ${job.company}
Location: ${job.location_text}
Tags: ${job.tags}
Description:
${desc}`;

return {
  json: {
    ...job,
    _ai_prompt: prompt,
    _ai_model: 'claude-sonnet-4-5',
    _ai_max_tokens: 500
  }
};

const originalJobs = $('Prepare AI Request').all();

return $input.all().map((item, index) => {
  const apiResponse = item.json;
  const originalJob = (originalJobs[index] || { json: {} }).json;

  let aiResult = {
    taiwan_eligible: 'unclear',
    reason: 'AI check unavailable',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };

  try {
    const content = apiResponse?.content?.[0]?.text || '';
    const match = content.match(/\{[\s\S]*\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      aiResult = { ...aiResult, ...parsed };
    }
  } catch (e) {
    // use defaults
  }

  // Rebuild original job without internal AI fields
  const job = { ...originalJob };
  delete job._ai_prompt;
  delete job._ai_model;
  delete job._ai_max_tokens;

  return {
    json: {
      ...job,
      taiwan_eligible: aiResult.taiwan_eligible,
      taiwan_reason: aiResult.reason,
      location_risk: aiResult.location_risk,
      timezone_risk: aiResult.timezone_risk,
      contractor_possible: aiResult.contractor_possible,
      ai_decision: aiResult.decision
    }
  };
});

const ASYNC_KEEP = [
  /\basync\b/i, /\basynchronous\b/i, /\bflexible hours\b/i,
  /\bflexible schedule\b/i, /\bdistributed team\b/i,
  /\bremote[- ]first\b/i, /\blow meeting\b/i,
  /\bwork across time zones\b/i, /\bno meeting\b/i,
  /\bself[- ]directed\b/i, /\boutcome[- ]based\b/i
];
const ASYNC_REJECT = [
  /\bstrict 9[ -]to[ -]5\b/i, /\bfixed (us|est|pst|cet|gmt) hours\b/i,
  /\bdaily (live|mandatory) calls\b/i,
  /\bmust overlap full business day\b/i,
  /\brequired (to be )?online (from|during) [0-9]/i
];

return $input.all().map(item => {
  const text = `${item.json.description || ''} ${item.json.tags || ''}`.toLowerCase();

  for (const pat of ASYNC_REJECT) {
    if (pat.test(text)) {
      return { json: { ...item.json, async_level: 'blocked', _async_reject: true } };
    }
  }

  let level = 'low';
  if (ASYNC_KEEP[0].test(text) || ASYNC_KEEP[1].test(text)) level = 'high';
  else if (ASYNC_KEEP.slice(2).some(p => p.test(text))) level = 'medium';

  return { json: { ...item.json, async_level: level } };
}).filter(item => !item.json._async_reject);

const ROLE_PRIORITY = [
  { cat: 'data_scientist', patterns: [/\bdata scientist\b/i, /\bjunior data scientist\b/i] },
  { cat: 'data_analyst', patterns: [/\bdata analyst\b/i, /\bbi analyst\b/i, /\bbusiness intelligence analyst\b/i] },
  { cat: 'marketing_analyst', patterns: [/\bmarketing analyst\b/i, /\bperformance marketing analyst\b/i, /\bgrowth analyst\b/i] },
  { cat: 'ai_specialist', patterns: [/\bai marketing\b/i, /\bai automation\b/i, /\bai workflow\b/i, /\bmartech analyst\b/i] },
  { cat: 'automation', patterns: [/\bautomation specialist\b/i, /\bautomation engineer\b/i] },
  { cat: 'creative_data', patterns: [/\bcreative strategist\b/i, /\bmarketing data\b/i] },
  { cat: 'adjacent', patterns: [/\banalyst\b/i, /\bmarketing\b/i, /\bdata\b/i, /\bgrowth\b/i, /\bautomation\b/i, /\bai\b/i] }
];

const TOP_CATS = ['data_scientist','data_analyst','marketing_analyst','ai_specialist','automation','creative_data'];

return $input.all().map(item => {
  const title = item.json.job_title || '';
  const desc = (item.json.description || '').substring(0, 500);
  const text = `${title} ${desc}`;

  let role_category = 'other';
  for (const { cat, patterns } of ROLE_PRIORITY) {
    if (patterns.some(p => p.test(text))) {
      role_category = cat;
      break;
    }
  }

  return { json: { ...item.json, role_category } };
}).filter(item => item.json.role_category !== 'other');

function scoreJob(job) {
  let score = 0;
  const text = `${job.location_text||''} ${job.description||''} ${job.tags||""}`.toLowerCase();

  // Taiwan eligibility (0-40 pts)
  if (job.taiwan_eligible === 'yes') {
    if (/worldwide|work from anywhere|global remote|anywhere in the world|apac/.test(text)) {
      score += /apac/.test(text) && !/worldwide|work from anywhere|global remote/.test(text) ? 30 : 40;
    } else {
      score += 20;
    }
  } else if (job.taiwan_eligible === 'unclear') {
    if (job.location_risk === 'low') score += 20;
    else if (job.location_risk === 'medium') score += 10;
  }
  // 0 pts if 'no'

  // Async fit (0-25 pts)
  if (job.async_level === 'high') score += 25;
  else if (job.async_level === 'medium') score += 20;
  else if (/distributed team/.test(text)) score += 15;
  else if (/remote[- ]first/.test(text)) score += 10;

  // Role fit (0-25 pts)
  const TOP = ['data_scientist','data_analyst','marketing_analyst','ai_specialist','automation','creative_data'];
  if (TOP.includes(job.role_category)) score += 25;
  else if (job.role_category === 'adjacent') score += 15;

  // Salary fit (0-25 pts)
  const salary = (job.salary || '').replace(/,/g, '');
  if (salary) {
    const nums = salary.match(/\d+/g);
    if (nums) {
      const maxNum = Math.max(...nums.map(Number));
      if (maxNum >= 5000) score += 25;       // monthly >= $5k
      else if (maxNum >= 3000) score += 15;  // monthly >= $3k
      else if (maxNum >= 60000) score += 25; // annual >= $60k
      else if (maxNum >= 36000) score += 15; // annual >= $36k
      else score += 10;
    } else {
      score += 10;
    }
  }

  return Math.min(score, 100);
}

function whyGoodFit(job, score) {
  const reasons = [];
  if (job.taiwan_eligible === 'yes') reasons.push('Taiwan eligible');
  if (job.async_level === 'high') reasons.push('Fully async');
  else if (job.async_level === 'medium') reasons.push('Flexible hours');
  const TOP = ['data_scientist','data_analyst','marketing_analyst','ai_specialist'];
  if (TOP.includes(job.role_category)) reasons.push('Strong role match for Jerry');
  if (job.salary) reasons.push('Salary listed');
  if (job.contractor_possible === 'yes') reasons.push('Contractor-friendly');
  return reasons.join('; ') || 'Potential fit';
}

return $input.all().map(item => {
  const job = item.json;
  const score = scoreJob(job);
  const decision = score >= 85 ? 'apply_immediately' : score >= 70 ? 'save_for_review' : 'reject';
  return {
    json: {
      ...job,
      score,
      decision,
      why_good_fit: whyGoodFit(job, score),
      date_found: new Date().toISOString().split('T')[0]
    }
  };
});

const job = $input.item.json;
const prompt = `Write a short cover letter for Jerry.

Jerry is based in Taiwan and wants async global remote work.

Background:
- Bilingual: English and Mandarin (grew up in California and Taiwan)
- Digital marketing background
- Data science bootcamp experience
- Technical: Python, SQL, Tableau, Power BI
- Marketing: Performance marketing, SEO, PPC, GA4, Meta Ads, Google Ads
- AI tools: ChatGPT, Claude, Gemini, Cursor
- Projects: Dashboards, EDA, machine learning, customer segmentation, fraud detection, marketing analytics

Job to apply for:
Title: ${job.job_title}
Company: ${job.company}
Salary: ${job.salary || 'Not specified'}
Role Category: ${job.role_category}
Why it fits: ${job.why_good_fit}

Make the letter specific to this job and company.
Explain how Jerry can help the company:
- Reduce manual analysis time
- Improve reporting speed
- Connect marketing and data
- Build AI-assisted workflows
- Turn messy data into business action

Keep it under 220 words.
Tone: confident, direct, human, not desperate.`;

return {
  json: {
    ...job,
    _cover_prompt: prompt
  }
};

const originals = $('Prepare Cover Letter Request').all();

return $input.all().map((item, i) => {
  const orig = (originals[i] || { json: {} }).json;
  const coverText = item.json?.content?.[0]?.text || 'Cover letter generation failed.';
  return {
    json: {
      ...orig,
      cover_letter_draft: coverText,
      _cover_prompt: undefined
    }
  };
});

// Collect all filtered jobs, sort by score, build digest
const items = $input.all();
const sorted = [...items].sort((a, b) => (b.json.score || 0) - (a.json.score || 0));

const top = sorted.filter(i => i.json.score >= 70).slice(0, 10);
const manualCheck = sorted.filter(i => i.json.taiwan_eligible === 'unclear' && i.json.score >= 70);

// Rejection stats
const allScored = $('Score Jobs').all();
const rejected = allScored.filter(i => i.json.score < 70 || i.json.ai_decision === 'reject');
const rejectedUSOnly = rejected.filter(i => /us.?only|usa.?only|united states only/i.test(`${i.json.taiwan_reason||''} ${i.json.location_text||''}`)).length;
const rejectedEUOnly = rejected.filter(i => /eu.?only|europe.?only|uk.?only/i.test(`${i.json.taiwan_reason||''} ${i.json.location_text||''}`)).length;
const rejectedHybrid = rejected.filter(i => /hybrid|onsite/i.test(`${i.json.taiwan_reason||''}`)).length;
const rejectedTimezone = rejected.filter(i => i.json.timezone_risk === 'high').length;

const dateStr = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Taipei' });

let html = `<h1>Daily Taiwan Eligible Async Remote Jobs</h1>`;
html += `<p><em>${dateStr} | Taiwan Time</em></p>`;
html += `<h2>Top Jobs Today (${top.length} found)</h2>`;

top.forEach((item, idx) => {
  const j = item.json;
  html += `<hr/><h3>${idx + 1}. ${j.job_title}</h3>`;
  html += `<p><strong>Company:</strong> ${j.company}</p>`;
  html += `<p><strong>Score:</strong> ${j.score}/100</p>`;
  html += `<p><strong>Taiwan Eligible:</strong> ${j.taiwan_eligible} — ${j.taiwan_reason || ''}</p>`;
  html += `<p><strong>Async Level:</strong> ${j.async_level}</p>`;
  html += `<p><strong>Timezone Risk:</strong> ${j.timezone_risk}</p>`;
  html += `<p><strong>Salary:</strong> ${j.salary || 'Not listed'}</p>`;
  html += `<p><strong>Why It Fits Jerry:</strong> ${j.why_good_fit}</p>`;
  html += `<p><a href="${j.job_url}">Apply → ${j.job_url}</a></p>`;
});

if (manualCheck.length > 0) {
  html += `<h2>⚠️ Manual Check (Eligibility Unclear)</h2>`;
  manualCheck.forEach(item => {
    const j = item.json;
    html += `<p>• <a href="${j.job_url}">${j.job_title}</a> at ${j.company} (Score: ${j.score}, Risk: ${j.location_risk})</p>`;
  });
}

html += `<h2>Rejected Summary</h2>`;
html += `<ul>`;
html += `<li>US only: ${rejectedUSOnly}</li>`;
html += `<li>EU/UK only: ${rejectedEUOnly}</li>`;
html += `<li>Hybrid/Onsite: ${rejectedHybrid}</li>`;
html += `<li>Timezone risk: ${rejectedTimezone}</li>`;
html += `<li>Total rejected: ${rejected.length}</li>`;
html += `</ul>`;

return [{ json: { digest_html: html, date: dateStr, top_count: top.length } }];
